function parseLedger(markdown) {
  // Investigation Brief 01 (binding):
  // - Treat only the markdown section whose heading line is exactly `## Transaction Ledger` as authoritative.
  // - Locate section boundaries with regular expressions anchored to whole heading lines.
  // - Ignore any ledger block that includes a line `provisional: true` (case insensitive).
  // - When the same transaction id appears in multiple non-provisional ledger blocks,
  //   the last such block in file order is the base row for that id.

  const headingRe = /^## Transaction Ledger\s*$/m;
  const match = headingRe.exec(markdown);
  if (!match) return [];

  const sectionStart = match.index + match[0].length;
  const after = markdown.slice(sectionStart);

  // Section extends until the next H2 heading (or EOF).
  const nextH2Idx = after.search(/^##\s+/m);
  const section = nextH2Idx === -1 ? after : after.slice(0, nextH2Idx);

  const byId = new Map();
  const blocks = section.split(/^###\s+/m).slice(1);

  for (const block of blocks) {
    if (/^\s*provisional\s*:\s*true\s*$/im.test(block)) {
      continue;
    }

    const lines = block.split("\n");
    const transactionId = (lines[0] || "").trim();
    if (!transactionId.startsWith("TXN-")) continue;

    const row = { transaction_id: transactionId };

    for (const line of lines) {
      const trimmed = line.trim();
      const idx = trimmed.indexOf(":");
      if (idx === -1) continue;

      const key = trimmed.slice(0, idx).trim().toLowerCase();
      const value = trimmed.slice(idx + 1).trim();

      if (key === "amount") {
        row.amount = Number(value);
      } else if (key === "owner") {
        row.owner = value;
      } else if (key === "status") {
        row.status = value;
      } else if (key === "date") {
        row.date = value;
      }
    }

    // last-in-file-order wins
    byId.set(transactionId, row);
  }

  return [...byId.values()];
}

module.exports = { parseLedger };
EOF
