const { sortByTransactionId } = require("../utils/sort");

// Used for deterministic pick when multiple sources touch a status.
const STATUS_ORDER = ["ok", "review", "compliance_hold", "void"];

function reconcileTransactions(parsed) {
  const byId = new Map();

  // base: ledger
  for (const row of parsed.ledger || []) {
    byId.set(row.transaction_id, { ...row });
  }

  // meetings (if present)
  for (const note of parsed.meetings || []) {
    const target = byId.get(note.transaction_id);
    if (!target) continue;
    if (note.owner) target.owner = note.owner;
    if (note.status) target.status = note.status;
    if (note.date) target.date = note.date;
  }

  // mail excerpts (if present)
  for (const msg of parsed.emails || []) {
    const target = byId.get(msg.transaction_id);
    if (!target) continue;
    if (msg.status) target.status = msg.status;
    if (msg.owner) target.owner = msg.owner;
  }

  // corrections must apply last.
  // Brief 08: reconciliation_report.jsonl is one object per winning correction,
  // sorted by notice_id ascending.
  const notices = [...(parsed.corrections || [])];
  notices.sort((a, b) => {
    const ea = a.effective || "";
    const eb = b.effective || "";
    if (ea < eb) return -1;
    if (ea > eb) return 1;
    return String(a.notice_id).localeCompare(String(b.notice_id));
  });

  // Track the last applied (winning) correction per (transaction_id, field)
  const winners = new Map();
  for (const notice of notices) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    const key = `${notice.transaction_id}::${notice.field}`;

    let previous = "";
    if (notice.field === "owner") {
      previous = target.owner ?? "";
      target.owner = notice.value;
    } else if (notice.field === "status") {
      previous = target.status ?? "";
      target.status = notice.value;
    } else if (notice.field === "date") {
      previous = target.date ?? "";
      target.date = notice.value;
    } else {
      continue;
    }

    winners.set(key, {
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: notice.field,
      previous_value: String(previous),
      new_value: notice.value,
      effective: notice.effective,
    });
  }

  const report = [...winners.values()].sort((a, b) =>
    String(a.notice_id).localeCompare(String(b.notice_id)),
  );

  const items = sortByTransactionId(
    [...byId.values()].map((row) => ({
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status).toLowerCase(),
      effective_date: row.date,
      amount_usd: Number(row.amount),
      exception_reason: null,
    })),
  );

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
EOF
